// ── 5. Magnets ──
const magnetMat = new THREE.MeshPhongMaterial({ color: 0xb8bcc0 });
function makeMagnet(xPos, letter) {
  const g = new THREE.Group();
  const cyl = new THREE.Mesh(new THREE.CylinderGeometry(0.7, 0.7, 0.8, 32), magnetMat);
  cyl.rotation.z = Math.PI / 2;
  g.add(cyl);
