function makeTextTexture(text, fg, bg, w, h, fontSize) {
  const c = document.createElement('canvas');
  c.width = w || 128; c.height = h || 128;
  const ctx = c.getContext('2d');
  if (bg) { ctx.fillStyle = bg; ctx.fillRect(0, 0, c.width, c.height); }
