const cableConnections = [[0, 1], [1, 2], [2, 3]];

function setHighlight(activeIndex) {
  componentGroups.forEach((g, i) => {
    g.traverse(obj => {
      if (obj.material) {
        const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
        mats.forEach(m => {
          if (m.emissive) {
            if (activeIndex === -1) {
              m.emissive.setHex(0x000000);
              m.opacity = m.userData?.baseOpacity ?? m.opacity;
              m.transparent = m.userData?.baseTransparent ?? m.transparent;
            } else if (activeIndex === i) {
              m.emissive.setHex(0x1a331a);
              m.opacity = m.userData?.baseOpacity ?? m.opacity;
            } else {
              m.emissive.setHex(0x000000);
              if (!m.userData) m.userData = {};
              if (m.userData.baseOpacity === undefined) {
                m.userData.baseOpacity = m.opacity;
                m.userData.baseTransparent = m.transparent;
              }
              m.transparent = true;
              m.opacity = 0.2;
            }
          }
        });
      }
    });
  });

  cableLines.forEach((cable, ci) => {
    const [a, b] = cableConnections[ci];
    const isActive = activeIndex === -1 || activeIndex === a || activeIndex === b;
    if (activeIndex === -1) {
      cable.material.color.copy(cable.userData.baseColor);
      cable.material.opacity = 1;
    } else if (isActive) {
      cable.material.color.setHex(0xffee44);
      cable.material.opacity = 1;
    } else {
      cable.material.color.copy(cable.userData.baseColor);
      cable.material.opacity = 0.15;
    }
  });
}

// ── 15. Resonance update ──
function updateResonance(B0) {
  let anyResonant = false;
  peakMeshes.forEach((peak, i) => {
    const isRes = Math.abs(B0 - peakFields[i]) < 0.4;
    if (isRes) {
      peak.scale.y = 1.6;
      peak.material.color.setHex(peakColors[i]);
      sampleMat.emissive.setHex(peakColors[i]);
      sampleMat.emissiveIntensity = 0.7;
      glowSprite.material.color.setHex(peakColors[i]);
      glowSprite.material.opacity = 0.6;
      anyResonant = true;
    } else {
      peak.scale.y = 1.0;
      peak.material.color.setHex(0xcc2222);
    }
  });
  if (!anyResonant) {
    sampleMat.emissive.setHex(0x000000);
    sampleMat.emissiveIntensity = 0;
    glowSprite.material.opacity = 0;
  }
  document.getElementById('fieldVal').textContent = B0.toFixed(1) + ' T';
}

