let fieldTween = null;
function tweenField(target) {
  fieldTween = {
    start: parseFloat(slider.value),
    target,
    startTime: performance.now(),
    duration: 1200
  };
}

// Patch animate loop via a post-frame hook
let _lastFrames = 0;
function _postFrame() {
  requestAnimationFrame(_postFrame);
  if (window.__figFrames === _lastFrames) return;
  _lastFrames = window.__figFrames;

  // Field tween
  if (fieldTween) {
    const t = Math.min(1, (performance.now() - fieldTween.startTime) / fieldTween.duration);
    const eased = t * t * (3 - 2 * t);
    const val = fieldTween.start + (fieldTween.target - fieldTween.start) * eased;
    slider.value = val;
    updateResonance(val);
    if (t >= 1) fieldTween = null;
  }

  // Trace
  if (traceActive) {
    const elapsed = performance.now() / 1000 - traceStartTime;
    const step = Math.floor(elapsed / TRACE_DUR);
    if (step > 3) {
      traceActive = false;
      setHighlight(-1);
    } else if (step !== traceStep) {
      traceStep = step;
      setHighlight(step);
    }
  }
}
_postFrame();

