// ── 17. Trace animation ──
let traceActive = false;
let traceStartTime = 0;
let traceStep = -1;
const TRACE_DUR = 1.5;

function startTrace() {
  traceActive = true;
  traceStartTime = performance.now() / 1000;
  traceStep = -1;
}

document.getElementById('btnTrace').addEventListener('click', startTrace);

// ── 18. Field tween ──
let fieldTween = null;
function tweenField(target) {
  fieldTween = {
    start: parseFloat(slider.value),
    target,
    startTime: performance.now(),
    duration: 1200
  };
}

// Post-frame hook
let _lastFrames = 0;
function _postFrame() {
  requestAnimationFrame(_postFrame);
  if (window.__figFrames === _lastFrames) return;
  _lastFrames = window.__figFrames;

  if (fieldTween) {
    const t = Math.min(1, (performance.now() - fieldTween.startTime) / fieldTween.duration);
    const eased = t * t * (3 - 2 * t);
    const val = fieldTween.start + (fieldTween.target - fieldTween.start) * eased;
    slider.value = val;
    updateResonance(val);
    if (t >= 1) fieldTween = null;
  }

  if (traceActive) {
    const elapsed = performance.now() / 1000 - traceStartTime;
    const step = Math.floor(elapsed / TRACE_DUR);
    if (step > 3) {
      traceActive = false;
      setHighlight(-1);
    } else if (step !== traceStep) {
      traceStep = step;
      setHighlight(step);
    }
  }
}
_postFrame();

// ── 19. Demo steps ──
window.goToStep = function(idx) {
  const steps = [
    { field: 4.7, trace: false },
    { field: 7.0, trace: false },
    { field: 7.0, trace: true }
  ];
  const s = steps[idx];
  if (!s) return;
  setHighlight(-1);
  tweenField(s.field);
  if (s.trace) setTimeout(startTrace, 1400);
};
